/// Hologram. Cost 1, Exhaust (Exhaust is dropped on upgrade — see
/// `card_upgrades_generated::upgrade_delta`, bead `sts2-rs-oq6nf`; C#
/// `Hologram.cs` OnUpgrade bumps Block 3→5 + `RemoveKeyword(Exhaust)`).
/// Gain block + return a card from the discard pile to hand.
///
/// Bead `sts2-rs-5om`: pile-search auto-picks the FIRST discard-pile card
/// and moves it back to hand. **Documented divergence (`sts2-rs-oq6nf`):**
/// C# opens a player `CardSelectCmd.FromSimpleGrid` over the discard pile
/// (`prefs(prompt, 1)` → auto-resolves at ≤1 card, prompts at ≥2). The
/// deterministic first-pick matches the game only for discard ≤1; the ≥2
/// player-choice case needs the `CardSelectCmd` plumbing (tracked with the
/// other multi-select stubs in `sts2-rs-1xmxp`/`sts2-rs-enwwr`), same class
/// as base Armaments/Headbutt under `sts2-rs-8ukqd`.
pub(crate) fn play_hologram(state: &mut CombatState, _t: Option<CreatureUid>) -> EffectResult {
    gain_block_player(state, current_card_block(state));
    // C# `CardSelectCmd.FromSimpleGrid(discard, prefs(prompt, 1))` →
    // `CardPileCmd.Add(_, Hand)`: auto-returns the lone card at ≤1 (no prompt,
    // no RNG), opens a single-pick player choice at ≥2 (same surface as
    // GraveBlast). The prior port auto-picked the first discard card even at
    // ≥2, so the lockstep saw an inline return where C# surfaces a card_select
    // (run-parity Defect HOLOGRAM card_select-vs-combat split).
    match state.player.discard.len() {
        0 => {}
        1 => {
            let uid = state.player.discard.remove(0);
            state.player.hand.push(uid);
        }
        _ => {
            let options: Vec<sts2_core::ChoiceOption> = state
                .player
                .discard
                .iter()
                .filter_map(|&uid| {
                    let card = state.cards.iter().find(|c| c.uid == uid)?;
                    Some(sts2_core::ChoiceOption {
                        card_id: card.card_id,
                        upgraded: card.upgraded,
                        card_uid: Some(uid),
                        source_pile: Some(sts2_core::cards::PileKind::Discard),
                    })
                })
                .collect();
            state.request_card_choice(
                sts2_core::ChoiceKind::AddFromDiscardToHand,
                options,
                1,
                1,
                false,
            );
        }
    }
    EffectResult::Resolved
}

